import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.util.zip.*;import java.nio.file.*;
public class Patch implements Opcodes {
 static final String P="com/raiiiden/warborn/",CLIENT=P+"client/util/NvgClient2",COMMON=P+"common/util/NvgLink2";static int hooks;
 static MethodInsnNode call(String o,String n,String d){return new MethodInsnNode(INVOKESTATIC,o,n,d,false);}static void clear(MethodNode m){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;}
 static byte[] patch(byte[] bytes)throws Exception{ClassNode c=new ClassNode();new ClassReader(bytes).accept(c,0);int before=hooks;for(MethodNode m:c.methods){
  if(c.name.equals(P+"client/event/ModKeybindings")&&m.name.equals("<clinit>"))for(AbstractInsnNode a:m.instructions.toArray())if(a instanceof LdcInsnNode l&&l.cst instanceof String key&&Set.of("key.warborn.toggle_helmet_top","key.warborn.toggle_special_vision").contains(key)){AbstractInsnNode value=a.getNext();if(!(value instanceof IntInsnNode))throw new IllegalStateException("key pattern");m.instructions.set(value,key.endsWith("helmet_top")?new IntInsnNode(BIPUSH,78):new InsnNode(ICONST_M1));hooks++;}
  if(c.name.equals(P+"client/event/ModKeybindings")&&m.name.equals("register"))for(AbstractInsnNode a:m.instructions.toArray())if(a instanceof FieldInsnNode f&&f.name.equals("TOGGLE_SPECIAL_VISION")){AbstractInsnNode event=a.getPrevious(),registration=a.getNext();if(!(event instanceof VarInsnNode)||!(registration instanceof MethodInsnNode mc)||!mc.name.equals("register"))throw new IllegalStateException("legacy key registration");m.instructions.remove(event);m.instructions.remove(a);m.instructions.remove(registration);hooks++;}
  if(c.name.equals(P+"client/event/ClientKeyEvents")){
   if(m.name.equals("onClientTick")){clear(m);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(call(CLIENT,"tick","(Ljava/lang/Object;)V"));m.instructions.add(new InsnNode(RETURN));hooks++;}
   if(m.name.equals("onKeyInput")){boolean animation=false;for(AbstractInsnNode a:m.instructions.toArray()){if(a instanceof TypeInsnNode n&&n.getOpcode()==NEW&&n.desc.equals(P+"common/network/ServerboundNVGArmAnimationPacket"))animation=true;if(animation&&a instanceof MethodInsnNode mc&&mc.owner.equals(P+"common/network/ModNetworking")&&mc.name.equals("sendToServer")){m.instructions.set(a,call(CLIENT,"key","(Ljava/lang/Object;)V"));animation=false;hooks++;}}}
  }
  if(c.name.equals(P+"client/shader/ShaderRegistry")&&m.name.equals("processShaders_Internal")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(call(CLIENT,"recover","(Ljava/lang/Object;)V"));m.instructions.insert(x);hooks++;for(AbstractInsnNode a:m.instructions.toArray())if(a instanceof MethodInsnNode mc&&mc.owner.equals("net/minecraft/client/renderer/GameRenderer")&&mc.name.equals("loadEffect")){InsnList y=new InsnList();y.add(new VarInsnNode(ALOAD,0));y.add(call(CLIENT,"loaded","(Ljava/lang/Object;)V"));m.instructions.insert(a,y);hooks++;}}
  if(c.name.equals(P+"client/network/ClientNVGBatteryEmptyHandler")&&m.name.equals("handle")){AbstractInsnNode last=null;for(AbstractInsnNode a:m.instructions)if(a.getOpcode()==RETURN)last=a;if(last==null)throw new IllegalStateException("empty return");m.instructions.insertBefore(last,call(CLIENT,"empty","()V"));hooks++;}
  if(c.name.equals(P+"common/event/HelmetBatteryTickHandler")){
   if(m.name.equals("onPlayerTick")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(call(COMMON,"event","(Ljava/lang/Object;)V"));m.instructions.insert(x);hooks++;}
   if(m.name.equals("setNVGActive")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(new VarInsnNode(ALOAD,2));x.add(call(COMMON,"authorize","(Ljava/lang/String;Ljava/lang/Object;)Ljava/lang/String;"));x.add(new VarInsnNode(ASTORE,1));m.instructions.insert(x);hooks++;}
  }
 }
 if(hooks==before)return bytes;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);ClassNode v=new ClassNode();new ClassReader(w.toByteArray()).accept(v,0);for(MethodNode m:v.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(v.name,m);return w.toByteArray();}
 public static void main(String[]a)throws Exception{Map<String,byte[]>entries=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[]b=z.getInputStream(e).readAllBytes();entries.put(e.getName(),e.getName().endsWith(".class")?patch(b):b);}}try(var f=Files.walk(Path.of(a[2]))){for(Path p:f.filter(p->p.toString().endsWith(".class")).toList())entries.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}if(hooks!=10)throw new IllegalStateException("hooks "+hooks);try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:entries.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}System.out.println("Verified ten key, visor, shader and server-state hooks");}
}
